// XML utilities for the Syrinscape soundset format.
// - Minimal, dependency-free XML parser (the Syrinscape XML is well-formed and
//   generated by a single tool, so a small recursive parser is enough).
// - `parseSoundsetXml` turns a Chapter XML file + the folder's audio files into
//   the element model the soundboard uses.
// - `generateSoundsetXml` builds a minimal Chapter XML from filename heuristics
//   for soundsets that ship without one.

export function decodeEntities(s) {
  return String(s)
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#([0-9]+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
}

export function encodeEntities(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

// A small recursive XML parser. Returns { name, attrs, children, text } nodes.
export function parseXml(input) {
  const s = input
    .replace(/^\uFEFF/, '')
    .replace(/<\?[\s\S]*?\?>/g, '')
    .replace(/<!--[\s\S]*?-->/g, '')
  let i = 0
  const len = s.length

  const isWs = (c) => c === ' ' || c === '\t' || c === '\n' || c === '\r'

  function skipWs() {
    while (i < len && isWs(s[i])) i++
  }

  function parseName() {
    let name = ''
    while (i < len && !isWs(s[i]) && s[i] !== '>' && s[i] !== '/' && s[i] !== '=') name += s[i++]
    return name
  }

  function parseNode() {
    if (i >= len) return null
    if (s[i] !== '<') {
      let raw = ''
      while (i < len && s[i] !== '<') raw += s[i++]
      return { name: '#text', attrs: {}, children: [], text: decodeEntities(raw).trim() }
    }
    i++ // '<'
    const name = parseName()
    const node = { name, attrs: {}, children: [], text: '' }
    skipWs()
    while (i < len && s[i] !== '>' && s[i] !== '/') {
      const attrName = parseName()
      skipWs()
      let value = ''
      if (s[i] === '=') {
        i++
        skipWs()
        const q = s[i]
        if (q === '"' || q === "'") {
          i++
          while (i < len && s[i] !== q) value += s[i++]
          i++
        } else {
          while (i < len && !isWs(s[i]) && s[i] !== '>' && s[i] !== '/') value += s[i++]
        }
      }
      node.attrs[attrName] = decodeEntities(value)
      skipWs()
    }
    if (s[i] === '/') {
      i += 2 // '/>'
      return node
    }
    i++ // '>'
    while (i < len) {
      if (s[i] === '<' && s[i + 1] === '/') break
      const c = parseNode()
      if (!c) break
      if (c.name === '#text') {
        if (c.text) node.text += (node.text ? ' ' : '') + c.text
      } else {
        node.children.push(c)
      }
    }
    if (s[i] === '<' && s[i + 1] === '/') {
      while (i < len && s[i] !== '>') i++
      i++
    }
    return node
  }

  skipWs()
  return parseNode()
}

const child = (node, name) => node?.children.find((c) => c.name === name) || null
const childrenOf = (node, name) => (node ? node.children.filter((c) => c.name === name) : [])
const text = (node) => (node ? node.text : '')
const num = (node, def = 0) => {
  if (!node || node.text === '') return def
  const v = parseFloat(node.text)
  return Number.isNaN(v) ? def : v
}

export function slugify(name) {
  return String(name)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64)
}

// --- file resolution ---

function fileBase(fn) {
  return fn.replace(/\.(ogg|mp3|wav)$/i, '')
}

export function buildFileIndex(files) {
  const byName = new Map()
  for (const f of files) {
    const key = fileBase(f).toLowerCase()
    if (!byName.has(key)) byName.set(key, [])
    byName.get(key).push(f)
  }
  return byName
}

function resolveTitle(title, byName, used) {
  const key = title.toLowerCase()
  const exact = byName.get(key)
  if (exact) {
    for (const f of exact) {
      if (!used.has(f)) {
        used.add(f)
        return f
      }
    }
  }
  // "Title 2", "Title 3", ... for duplicate titles in the source XML
  const prefix = key + ' '
  for (const [k, fs] of byName) {
    if (k.startsWith(prefix)) {
      for (const f of fs) {
        if (!used.has(f)) {
          used.add(f)
          return f
        }
      }
    }
  }
  return null
}

// --- Syrinscape chapter -> element model ---

const ELEMENT_NODES = ['MusicElement', 'SFXElement', 'OneshotElement', 'LoopElement']

export function parseSoundsetXml(xmlString, files) {
  const root = parseXml(xmlString)
  if (!root || root.name !== 'Chapter') return null

  const byName = buildFileIndex(files)
  const used = new Set()

  const samples = childrenOf(child(root, 'Samples'), 'SoundSample')
  const byUuid = new Map()
  for (const s of samples) {
    byUuid.set(text(child(s, 'Uuid')), text(child(s, 'Title')))
  }

  function parseElements(containerName, sectionKind) {
    const container = child(root, containerName)
    if (!container) return []
    const out = []
    for (const el of container.children.filter((c) => ELEMENT_NODES.includes(c.name))) {
      const slug = text(child(el, 'Slug'))
      const title = text(child(el, 'Title'))
      const gain = num(child(el, 'InitialGain'), 1)
      const randomise = text(child(el, 'RandomisePlaylist'))
      const minTW = num(child(el, 'MinTriggerWait'))
      const maxTW = num(child(el, 'MaxTriggerWait'))
      const startMin = num(child(el, 'MinStartDelay'))
      const startMax = num(child(el, 'MaxStartDelay'))
      const reverb = text(child(el, 'ReverbPreset'))
      const bypassPosition = text(child(el, 'BypassPosition')) === 'true'
      const hasPosition =
        !bypassPosition &&
        (child(el, 'MinAngle') || child(el, 'MaxAngle') || child(el, 'MinDistance') || child(el, 'MaxDistance'))
      const position = hasPosition
        ? {
            minAngle: num(child(el, 'MinAngle'), -180),
            maxAngle: num(child(el, 'MaxAngle'), 180),
            minDistance: num(child(el, 'MinDistance'), 0),
            maxDistance: num(child(el, 'MaxDistance'), 0),
          }
        : null

      const entries = childrenOf(child(el, 'Playlist'), 'PlaylistEntry')
      const resolved = []
      for (const pe of entries) {
        const uuid = text(child(pe, 'SampleFile'))
        const titleName = byUuid.get(uuid) || uuid
        const f = resolveTitle(titleName, byName, used)
        if (f) resolved.push({ name: fileBase(f), file: f })
      }

      if (!resolved.length) continue

      let kind
      if (sectionKind === 'oneshot') kind = 'oneshot'
      else if (sectionKind === 'loop') kind = 'loop'
      else kind = maxTW > 0 ? 'random' : 'loop'

      out.push({
        id: slug || `gen-${slugify(title)}-${out.length}`,
        name: title || resolved.map((r) => r.name).join(', '),
        kind,
        gain,
        randomise,
        reverb,
        position,
        files: resolved,
        trigger: { min: minTW, max: maxTW, startMin, startMax },
      })
    }
    return out
  }

  const elements = [
    ...parseElements('MusicElements', 'music'),
    ...parseElements('SfxElements', 'sfx'),
    ...parseElements('LoopElements', 'loop'),
    ...parseElements('OneshotElements', 'oneshot'),
  ]

  const moods = childrenOf(child(root, 'Moods'), 'Mood').map((m) => {
    const params = {}
    for (const ep of childrenOf(child(m, 'ElementParameters'), 'ElementParameter')) {
      const slug = text(child(ep, 'ElementSlug'))
      if (slug) {
        params[slug] = {
          plays: text(child(ep, 'Plays')) === 'true',
          volume: num(child(ep, 'Volume'), 1),
        }
      }
    }
    return { name: text(child(m, 'Title')), params }
  })

  return {
    title: text(child(root, 'Title')),
    gain: num(child(root, 'InitialGain'), 1),
    elements,
    moods,
  }
}

// --- filename heuristics -> minimal Chapter XML ---

const LOOP_RE = /(^|[^a-z])(loop|loops|fadeloop|ambience|drone)([^a-z]|$)/i
const AUDIO_RE = /\.(ogg|mp3|wav)$/i

function groupKey(name) {
  // Strip a trailing version/counter: "Foo 01", "Foo_02", "Foo-3", "Foo (14)".
  return name.replace(/[\s._-]*\(?\d{1,3}\)?$/, '').trim()
}

export function elementsFromFiles(files) {
  const audio = files.filter((f) => AUDIO_RE.test(f))
  const groups = new Map()

  for (const f of audio) {
    const name = fileBase(f)
    const key = groupKey(name)
    const isLoop = LOOP_RE.test(name) || LOOP_RE.test(key)
    const bucket = isLoop ? 'loops' : 'oneshots'
    const gkey = `${bucket}::${key}`
    if (!groups.has(gkey)) groups.set(gkey, { name: key, isLoop, files: [] })
    groups.get(gkey).files.push(f)
  }

  const elements = []
  for (const g of groups.values()) {
    g.files.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
    const id = slugify(g.name) || 'group'
    elements.push({
      id,
      name: g.name,
      kind: g.isLoop ? 'loop' : 'oneshot',
      gain: 1,
      randomise: 'random',
      files: g.files.map((f) => ({ name: fileBase(f), file: f })),
      trigger: { min: 0, max: 0, startMin: 0, startMax: 0 },
    })
  }
  elements.sort((a, b) => a.name.localeCompare(b.name))
  return elements
}

export function generateSoundsetXml(folderName, files) {
  const title = folderName.replace(/^Syrinscape\s*-\s*/i, '').trim()
  const elements = elementsFromFiles(files)
  const loops = elements.filter((e) => e.kind === 'loop')
  const oneshots = elements.filter((e) => e.kind === 'oneshot')

  const samples = []
  let n = 0
  const sampleLines = (el) => {
    const lines = []
    for (const f of el.files) {
      n += 1
      const uuid = `gen-${String(n).padStart(6, '0')}-${el.id}`
      samples.push({ uuid, title: f.name })
      lines.push(
        `          <PlaylistEntry>\n` +
          `            <SampleFile>${uuid}</SampleFile>\n` +
          `            <MinGain>1.0</MinGain>\n` +
          `            <MaxGain>1.0</MaxGain>\n` +
          `            <MinElementIntensity>0.0</MinElementIntensity>\n` +
          `            <MaxElementIntensity>1.0</MaxElementIntensity>\n` +
          `          </PlaylistEntry>`
      )
    }
    return lines.join('\n')
  }

  const elementBlock = (el, extra) => {
    const kindTag = el.kind === 'loop' ? 'MusicElement' : 'OneshotElement'
    const inner = el.kind === 'loop'
      ? `      <MinStartDelay>0.0</MinStartDelay>\n` +
        `      <MaxStartDelay>0.0</MaxStartDelay>\n` +
        `      <RandomisePlaylist>random</RandomisePlaylist>\n` +
        `      <RepeatPlaylist>true</RepeatPlaylist>\n` +
        `      <AllowPlaylistOverlap>false</AllowPlaylistOverlap>\n` +
        `      <MinTriggerWait>-15.0</MinTriggerWait>\n` +
        `      <MaxTriggerWait>-15.0</MaxTriggerWait>`
      : `      <IsGlobalOneshot>false</IsGlobalOneshot>\n` +
        `      <RandomisePlaylist>random</RandomisePlaylist>`
    return (
      `      <${kindTag}>\n` +
      `        <Title>${encodeEntities(el.name)}</Title>\n` +
      `        <Slug>${encodeEntities(el.id)}</Slug>\n` +
      `        <InitialGain>${el.gain}</InitialGain>\n` +
      `        <InitialIntensity>1.0</InitialIntensity>\n` +
      `        <Playlist>\n${sampleLines(el)}\n        </Playlist>\n` +
      inner +
      `\n      </${kindTag}>`
    )
  }

  const loopsBlock = loops.map((el) => elementBlock(el)).join('\n')
  const oneshotsBlock = oneshots.map((el) => elementBlock(el)).join('\n')
  const samplesBlock = samples
    .map(
      (s) =>
        `    <SoundSample>\n` +
        `      <Uuid>${s.uuid}</Uuid>\n` +
        `      <Extension>ogg</Extension>\n` +
        `      <Title>${encodeEntities(s.title)}</Title>\n` +
        `      <Duration>0</Duration>\n` +
        `    </SoundSample>`
    )
    .join('\n')

  const xml =
    `<Chapter>\n` +
    `  <Slug>${slugify(title)}</Slug>\n` +
    `  <Title>${encodeEntities(title)}</Title>\n` +
    `  <InitialGain>1.0</InitialGain>\n` +
    `  <Samples>\n${samplesBlock}\n  </Samples>\n` +
    `  <MusicElements>\n${loopsBlock}\n  </MusicElements>\n` +
    `  <SfxElements>\n  </SfxElements>\n` +
    `  <LoopElements>\n  </LoopElements>\n` +
    `  <OneshotElements>\n${oneshotsBlock}\n  </OneshotElements>\n` +
    `  <Moods>\n  </Moods>\n` +
    `</Chapter>\n`

  return xml
}
